from typing import List

def minPath(grid: List[List[int]], k: int) -> List[int]:
    n = len(grid)
    # Find the cell containing 1
    start_i = start_j = -1
    for i in range(n):
        for j in range(n):
            if grid[i][j] == 1:
                start_i, start_j = i, j
                break
        if start_i != -1:
            break

    if start_i == -1:
        return []  # Should not happen per problem statement

    cur_i, cur_j = start_i, start_j
    path = [1]  # first cell is always 1

    # Directions: up, down, left, right
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]

    # Build the path of length k
    for _ in range(1, k):
        best_val = None
        best_i = best_j = -1
        for di, dj in dirs:
            ni, nj = cur_i + di, cur_j + dj
            if 0 <= ni < n and 0 <= nj < n:
                val = grid[ni][nj]
                if best_val is None or val < best_val:
                    best_val = val
                    best_i, best_j = ni, nj
        path.append(best_val)
        cur_i, cur_j = best_i, best_j

    return path

def cycpattern_check(a, b):
    # If b is empty, trivially true (empty substring)
    if not b:
        return True
    n = len(b)
    # generate all rotations
    for i in range(n):
        # rotation starting at i
        rot = b[i:] + b[:i]
        if rot in a:
            return True
    return False

