def parse_nested_parens(paren_string: str) -> List[int]:
    """
    Input to this function is a string represented multiple groups for nested parentheses separated by spaces.
    For each of the group, output the deepest level of nesting of parentheses.
    """
    results = []
    for group in paren_string.split():
        depth = 0
        max_depth = 0
        for ch in group:
            if ch == '(':
                depth += 1
                if depth > max_depth:
                    max_depth = depth
            elif ch == ')':
                depth -= 1
        results.append(max_depth)
    return results

def count_nums(arr):
    """
    Returns the number of elements in arr whose sum of signed digits is greater than 0.
    For negative numbers, the first (most significant) digit is treated as negative,
    while the remaining digits are positive.
    """
    count = 0
    for n in arr:
        if n >= 0:
            # Positive numbers: all digits are positive
            digit_sum = sum(int(ch) for ch in str(n))
        else:
            # Negative numbers: first digit negative, rest positive
            abs_str = str(-n)          # digits of the absolute value
            digits = [int(ch) for ch in abs_str]
            if digits:
                # Signed sum: first digit negative, others positive
                digit_sum = -digits[0] + sum(digits[1:])
            else:
                digit_sum = 0
        if digit_sum > 0:
            count += 1
    return count

import math

def words_in_sentence(sentence):
    """
    Returns a string containing the words from the original sentence whose lengths are prime numbers.
    The order of the words is preserved.
    """
    def is_prime(n):
        """Check if n is a prime number."""
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        limit = int(math.isqrt(n))
        for i in range(3, limit + 1, 2):
            if n % i == 0:
                return False
        return True

    # Split the sentence into words
    words = sentence.split()
    # Keep only words whose lengths are prime
    prime_words = [word for word in words if is_prime(len(word))]
    # Join the selected words with spaces
    return " ".join(prime_words)

