    True
    >>> monotonic([1, 20, 4, 10])
    False
    >>> monotonic([4, 1, 0, -10])
    True
    """
    if not l:
        return True

    direction = None
    for i in range(len(l) - 1):
        if l[i] < l[i + 1]:
            current_dir = 1
        elif l[i] > l[i + 1]:
            current_dir = -1
        else:
            continue

        if direction is None:
            direction = current_dir
        elif direction != current_dir:
            return False

    return True

